"""Author the five course-specific practice exams. Answers are displayed only on submission."""
import json, random
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
tests = []
current = None
def S(a,b=None): return {'kind':'slides','first':a,'last':b or a}
def D(a,b=None): return {'kind':'documents','first':a,'last':b or a}
def R(n,p=1): return {'kind':'reading','reading':n,'page':p}
def begin(n,title,focus):
    global current
    current={'id':n,'letter':chr(64+n),'title':title,'focus':focus,'questions':[]}
    tests.append(current)
def mc(stem,correct,wrong,explanation,sources,cartoon=None,statements=None,order=False):
    i=len(current['questions'])+1
    options=[correct]+wrong
    random.Random(current['id']*100+i).shuffle(options)
    q={'id':f"t{current['id']}-q{i:02d}",'type':'mc','section':'cartoons' if cartoon else 'knowledge','stem':stem,'options':options,'answer':options.index(correct),'explanation':explanation,'sources':sources}
    if cartoon:q['cartoon']=cartoon
    if statements:q['statements']=statements
    if order:q['chronology']=True
    current['questions'].append(q)
def combo(stem,statements,correct,explanation,sources):
    opts=['A only','B only','C only','A and B only','A and C only','B and C only','All three (A, B, and C)']
    mc(stem,correct,[o for o in opts if o!=correct],explanation,sources,statements=statements)
def fill(stem,answer,variants,explanation,sources):
    i=len(current['questions'])+1
    current['questions'].append({'id':f"t{current['id']}-q{i:02d}",'type':'fill','section':'blanks','stem':stem,'answer':answer,'accepted':[answer]+variants,'explanation':explanation,'sources':sources})
def short(stem,model,rubric,sources):
    i=len(current['questions'])+1
    current['questions'].append({'id':f"t{current['id']}-q{i:02d}",'type':'short','section':'short','stem':stem,'model':model,'rubric':rubric,'sources':sources})

